    fbBuilder.addOffset(4, OBSERVER_IDOffset);
    fbBuilder.addOffset(5, OBSERVER_POSITION_MOffset);
    fbBuilder.addOffset(6, OBSERVER_VELOCITY_M_PER_SOffset);
